#!/usr/bin/env python3
"""Deterministic JSONL event generator + schema validator (stdlib only).

Same (seed, schema) always yields byte-identical records: all randomness is
drawn from random.Random(seed) in a fixed traversal order, and timestamps are
derived from the PRNG rather than the wall clock. Only the log line carries a
real timestamp.
"""
import argparse
import json
import os
import random
import re
import sys
from datetime import datetime, timedelta, timezone

EPOCH = datetime(2020, 1, 1, tzinfo=timezone.utc)
WORDS = "abcdefghijklmnopqrstuvwxyz"


def _rand_token(rng, lo, hi):
    [secret redacted]


def synth(node, rng):
    """Synthesize a value that satisfies the (subset of) JSON Schema in node."""
    if not isinstance(node, dict):
        return None
    if "enum" in node:
        return rng.choice(node["enum"])
    t = node.get("type")
    if t == "string":
        fmt = node.get("format")
        if fmt == "date-time":
            secs = rng.randint(0, 315360000)
            return (EPOCH + timedelta(seconds=secs)).strftime("%Y-%m-%dT%H:%M:%S+00:00")
        if fmt == "uuid":
            return "%08x-%04x-%04x-%04x-%012x" % (
                rng.getrandbits(32), rng.getrandbits(16), rng.getrandbits(16),
                rng.getrandbits(16), rng.getrandbits(48),
            )
        if "pattern" in node:
            if node["pattern"] == "^evt-[0-9a-f]{16}$":
                return "evt-%016x" % rng.getrandbits(64)
        return _rand_token(rng, node.get("minLength", 3), node.get("maxLength", 12))
    if t == "integer":
        return rng.randint(node.get("minimum", 0), node.get("maximum", 100))
    if t == "number":
        return round(rng.uniform(node.get("minimum", 0.0), node.get("maximum", 1.0)), 4)
    if t == "boolean":
        return rng.random() < 0.5
    if t == "array":
        n = rng.randint(node.get("minItems", 0), node.get("maxItems", 3))
        return [synth(node.get("items", {}), rng) for _ in range(n)]
    if t == "object":
        return {k: synth(v, rng) for k, v in node.get("properties", {}).items()}
    return None


def generate(seed, count, schema):
    rng = random.Random(seed)
    return [{"__index__": i, **synth(schema, rng)} for i in range(count)]


def _type_ok(value, t):
    if t == "integer":
        return isinstance(value, int) and not isinstance(value, bool)
    if t == "number":
        return isinstance(value, (int, float)) and not isinstance(value, bool)
    if t == "boolean":
        return isinstance(value, bool)
    m = {"object": dict, "array": list, "string": str, "null": type(None)}
    return t in m and isinstance(value, m[t])


def _is_datetime(text):
    try:
        datetime.fromisoformat(text.replace("Z", "+00:00"))
        return True
    except ValueError:
        return False


def validate(value, schema, path="$", errors=None):
    """Return a list of human-readable validation errors (empty == valid)."""
    if errors is None:
        errors = []
    if not isinstance(schema, dict):
        return errors
    t = schema.get("type")
    if t and not _type_ok(value, t):
        errors.append(f"{path}: expected {t}, got {type(value).__name__}")
        return errors
    if "enum" in schema and value not in schema["enum"]:
        errors.append(f"{path}: value not in enum {schema['enum']}")
    if isinstance(value, str):
        if "minLength" in schema and len(value) < schema["minLength"]:
            errors.append(f"{path}: shorter than minLength")
        if "maxLength" in schema and len(value) > schema["maxLength"]:
            errors.append(f"{path}: longer than maxLength")
        if "pattern" in schema and not re.search(schema["pattern"], value):
            errors.append(f"{path}: does not match pattern")
        fmt = schema.get("format")
        if fmt == "date-time" and not _is_datetime(value):
            errors.append(f"{path}: not a date-time")
    elif isinstance(value, bool):
        pass
    elif isinstance(value, (int, float)):
        if "minimum" in schema and value < schema["minimum"]:
            errors.append(f"{path}: below minimum")
        if "maximum" in schema and value > schema["maximum"]:
            errors.append(f"{path}: above maximum")
    elif isinstance(value, list):
        if "minItems" in schema and len(value) < schema["minItems"]:
            errors.append(f"{path}: fewer than minItems")
        if "maxItems" in schema and len(value) > schema["maxItems"]:
            errors.append(f"{path}: more than maxItems")
        items = schema.get("items")
        if isinstance(items, dict):
            for i, item in enumerate(value):
                validate(item, items, f"{path}[{i}]", errors)
    elif isinstance(value, dict):
        for req in schema.get("required", []):
            if req not in value:
                errors.append(f"{path}: missing required {req}")
        props = schema.get("properties", {})
        for key, sub in value.items():
            [secret redacted]
                validate(sub, props[key], f"{path}.{key}", errors)
            elif schema.get("additionalProperties") is False:
                errors.append(f"{path}: unexpected property {key}")
    return errors


def _dumps(record):
    return (json.dumps(record, sort_keys=[secret redacted]


def _ensure_parent(path):
    parent = os.path.dirname(os.path.abspath(path))
    if parent:
        os.makedirs(parent, exist_ok=True)


def run(seed, count, schema_path, mode, out_path, log_path="logs/gen.log"):
    with open(schema_path, "r", encoding="utf-8") as fh:
        schema = json.load(fh)

    records = generate(seed, count, schema)
    events = [{k: v for k, v in r.items() if k != "__index__"} for r in records]
    lines = [_dumps(e) for e in events]

    _ensure_parent(out_path)
    with open(out_path, "ab" if mode == "append" else "wb") as fh:
        for line in lines:
            fh.write(line)

    valid = sum(1 for e in events if not validate(e, schema))

    # Per-seed sample/metadata file so distinct seeds are observable under data/.
    side = os.path.join(os.path.dirname(os.path.abspath(out_path)), f"metadata_seed{seed}.jsonl")
    with open(side, "wb") as fh:
        for line in lines:
            fh.write(line)

    entry = {
        "seed": seed,
        "count": count,
        "schema": schema_path,
        "mode": mode,
        "out": out_path,
        "valid_records": valid,
        "total_records": len(events),
        "timestamp": datetime.now(timezone.utc).isoformat(),
    }
    _ensure_parent(log_path)
    with open(log_path, "a", encoding="utf-8", newline="\n") as lf:
        lf.write(json.dumps(entry, sort_keys=[secret redacted]
    return entry


def main(argv=None):
    p = argparse.ArgumentParser(description="Deterministic JSONL event generator")
    p.add_argument("--seed", type=int, required=True)
    p.add_argument("--count", type=int, required=True)
    p.add_argument("--schema", required=True)
    p.add_argument("--mode", choices=["append", "overwrite"], default="overwrite")
    p.add_argument("--out", required=True)
    p.add_argument("--log", default="logs/gen.log")
    args = p.parse_args(argv)

    if args.count < 0:
        p.error("--count must be >= 0")
    entry = run(args.seed, args.count, args.schema, args.mode, args.out, args.log)
    print(json.dumps(entry, sort_keys=[secret redacted]
    return 0


if __name__ == "__main__":
    sys.exit(main())

