#!/usr/bin/env python3
"""Subtask4: automatic symbolic planner.

Consumes a domain (operator) JSON + a goal JSON, decomposes the goal into a
dependency DAG via backward chaining, and emits:
  * a metrics report (--report)         with the 5 required keys
  * a plan export  (--plan-export)      for structural / DAG validation

CLI:
  python3 subtask4_planner.py \
      --domain domain/planner.domain.json \
      --goal   domain/planner.goal.json \
      --report reports/planner_report.json \
      --plan-export reports/plan_export.json

Stdlib only.
"""
import argparse
import json
import os
import time

SAT = -1  # sentinel: fact already satisfied by the initial state


class CycleError(Exception):
    pass


def _load(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def _as_list(x):
    if x is None:
        return []
    if isinstance(x, (list, tuple)):
        return list(x)
    return [x]


def _norm_ops(domain):
    """Accept several operator encodings and normalise to name -> {pre, add}."""
    ops = domain.get("operators", domain.get("actions", domain))
    out = {}
    if isinstance(ops, dict):
        items = list(ops.items())
    elif isinstance(ops, list):
        items = [(o.get("name", "op%d" % i), o) for i, o in enumerate(ops)]
    else:
        raise ValueError("unsupported operators format")
    for i, (name, o) in enumerate(items):
        eff = o.get("effects") if isinstance(o.get("effects"), dict) else {}
        pre = o.get("pre", o.get("preconditions", []))
        add = o.get("add", o.get("add_effects", eff.get("add")))
        out[name] = {"name": name, "pre": _as_list(pre), "add": _as_list(add)}
    return out


def plan(domain, goal):
    """Backward-chaining planner returning a DAG ({nodes, edges}) + metrics."""
    operators = _norm_ops(domain)
    initial = _as_list(goal.get("initial", domain.get("initial", [])))
    goals = _as_list(goal.get("goal", goal.get("goals", [])))

    facts = set(initial)
    nodes = []
    edges = []
    memo = {}
    expansions = 0
    unsatisfied = []

    def add_edge(a, b):
        if a == b:
            return
        src, dst = "n%d" % a, "n%d" % b
        edges.append({"from": src, "to": dst, "source": src, "target": dst})

    def achieve(fact, stack):
        nonlocal expansions
        if fact in facts:
            return SAT
        if fact in memo:
            return memo[fact]
        if fact in stack:
            raise CycleError(fact)
        for name, op in operators.items():
            if fact not in op["add"]:
                continue
            expansions += 1
            deps = []
            ok = True
            for p in op["pre"]:
                d = achieve(p, stack | frozenset([fact]))
                if d is None:
                    ok = False
                    break
                if d != SAT:
                    deps.append(d)
            if not ok:
                continue
            idx = len(nodes)
            nodes.append({
                "id": "n%d" % idx,
                "operator": name,
                "produces": fact,
                "preconditions": list(op["pre"]),
            })
            memo[fact] = idx
            for d in deps:
                add_edge(d, idx)
            return idx
        return None

    for g in goals:
        try:
            idx = achieve(g, frozenset())
        except CycleError:
            idx = None
        if idx is None:
            unsatisfied.append(g)
        elif idx != SAT:
            facts.add(g)

    topo = _toposort([n["id"] for n in nodes], edges)
    return {
        "initial": initial,
        "goal": goals,
        "nodes": nodes,
        "edges": edges,
        "unsatisfied": unsatisfied,
        "nodes_expanded": expansions,
        "heuristic_cost": sum(len(n["preconditions"]) for n in nodes),
        "topological_order": topo,
    }


def _toposort(ids, edges):
    indeg = {i: 0 for i in ids}
    adj = {i: [] for i in ids}
    for e in edges:
        a, b = e["from"], e["to"]
        if a in indeg and b in indeg and a != b:
            adj[a].append(b)
            indeg[b] += 1
    queue = [i for i in ids if indeg[i] == 0]
    order = []
    while queue:
        cur = queue.pop(0)
        order.append(cur)
        for nxt in adj[cur]:
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                queue.append(nxt)
    return order


def _dump(path, obj):
    d = os.path.dirname(path)
    if d:
        os.makedirs(d, exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(obj, f, indent=2, sort_keys=True)


def main(argv=None):
    ap = argparse.ArgumentParser(description="Symbolic DAG planner")
    ap.add_argument("--domain", default="domain/planner.domain.json")
    ap.add_argument("--goal", default="domain/planner.goal.json")
    ap.add_argument("--report", default="reports/planner_report.json")
    ap.add_argument("--plan-export", dest="plan_export",
                    default="reports/plan_export.json")
    args = ap.parse_args(argv)

    t0 = time.perf_counter()
    domain = _load(args.domain)
    goal = _load(args.goal)
    result = plan(domain, goal)
    schedule_latency = time.perf_counter() - t0

    n_goals = max(len(result["goal"]), 1)
    success_rate = 1.0 if not result["unsatisfied"] else round(
        (n_goals - len(result["unsatisfied"])) / n_goals, 6)

    report = {
        "success_rate": success_rate,
        "plan_success": not result["unsatisfied"],
        "plan_length": len(result["nodes"]),
        "nodes_expanded": result["nodes_expanded"],
        "heuristic_cost": result["heuristic_cost"],
        "schedule_latency": schedule_latency,
        "nodes": len(result["nodes"]),
        "edges": len(result["edges"]),
        "unsatisfied": result["unsatisfied"],
    }
    _dump(args.report, report)

    export = {
        "domain": domain.get("name", "domain"),
        "initial": result["initial"],
        "goal": result["goal"],
        "nodes": result["nodes"],
        "edges": result["edges"],
        "topological_order": result["topological_order"],
        "plan_length": len(result["nodes"]),
    }
    _dump(args.plan_export, export)

    print(json.dumps(report, sort_keys=[secret redacted]
    return 0 if not result["unsatisfied"] else 1


if __name__ == "__main__":
    raise SystemExit(main())

